const fs = require\('fs'\);
const crypto = require\('crypto'\);

// --- 1. Read the remapping CSV ---
const remapCsv = fs.readFileSync\('REMAPEO-CATEGORIAS - REMAPEO-CATEGORIAS.csv', 'utf8'\);
const remapLines = remapCsv.replace\(/^\\uFEFF/, ''\).split\('\\n'\).slice\(1\).filter\(l => l.trim\(\)\);
const remap = {};
for \(const line of remapLines\) {
  // Simple parse: first comma separates product from category
  const match = line.match\(/^\\"?\(.+?\)\\"?,\([A-Z ]+\)/i\);
  if \(match\) {
    const prod = match[1].replace\(/\\"\\"/g, '\\"'\).trim\(\);
    const cat = match[2].trim\(\).toUpperCase\(\);
    remap[prod] = cat;
  }
}
console.log\('Remapped products:', Object.keys\(remap\).length\);

// --- 2. Define new categories with UUIDs ---
const newCategories = {
  'ROUND DUCT':           { id: crypto.randomUUID\(\), title: 'Round Duct',           slug: 'round-duct' },
  'FITTINGS':             { id: crypto.randomUUID\(\), title: 'Fittings',             slug: 'fittings' },
  'RESIDENTIAL FITTINGS': { id: crypto.randomUUID\(\), title: 'Residential Fittings', slug: 'residential-fittings' },
  'MISCELLANEOUS':        { id: crypto.randomUUID\(\), title: 'Miscellaneous',        slug: 'miscellaneous' },
  'CIRCLELINED PRODUCTS': { id: crypto.randomUUID\(\), title: 'Circlelined Products', slug: 'circlelined-products' },
  'VENTING':              { id: crypto.randomUUID\(\), title: 'Venting',              slug: 'venting' },
};

// Fix: FLEX CONNECTOR -> MISCELLANEOUS
for \(const [k, v] of Object.entries\(remap\)\) {
  if \(v === 'FLEX CONNECTOR'\) remap[k] = 'MISCELLANEOUS';
}

console.log\('\\\\nNew categories:'\);
for \(const [key, cat] of Object.entries\(newCategories\)\) {
  const count = Object.values\(remap\).filter\(v => v === key\).length;
  console.log\('  ' + cat.title + ' \(' + cat.id + '\) - ' + count + ' products'\);
}

// --- 3. Read existing Product+List.csv to get product data ---
function parseCsv\(csvText\) {
  const text = csvText.replace\(/^\\uFEFF/, ''\);
  const rows = [];
  let field = '', row = [], inQ = false;
  for \(let i = 0; i < text.length; i++\) {
    const c = text[i];
    if \(inQ\) {
      if \(c === '\\"'\) { if \(text[i+1] === '\\"'\) { field += '\\"'; i++; } else inQ = false; }
      else field += c;
      continue;
    }
    if \(c === '\\"'\) { inQ = true; continue; }
    if \(c === ','\) { row.push\(field\); field = ''; continue; }
    if \(c === '\\n'\) { row.push\(field\); field = ''; rows.push\(row\); row = []; continue; }
    if \(c === '\\r'\) continue;
    field += c;
  }
  row.push\(field\); rows.push\(row\);
  return rows;
}

const productRows = parseCsv\(fs.readFileSync\('data/Product+List.csv', 'utf8'\)\);
const productHeader = productRows[0];
const titleIdx = productHeader.indexOf\('Title'\);
const statusIdx = productHeader.indexOf\('Status'\);
const catRefIdx = productHeader.indexOf\('ProductCategories_multireference'\);
const idIdx = productHeader.indexOf\('ID'\);

console.log\('\\\\nProduct CSV columns: Title=' + titleIdx + ' Status=' + statusIdx + ' CatRef=' + catRefIdx + ' ID=' + idIdx\);

// Build lookup: product title -> new category ID
const titleToCatId = {};
for \(const [prodTitle, catKey] of Object.entries\(remap\)\) {
  if \(newCategories[catKey]\) {
    titleToCatId[prodTitle] = newCategories[catKey].id;
  }
}

// --- 4. Update Product+List.csv ---
let unmatchedProducts = [];
for \(let i = 1; i < productRows.length; i++\) {
  const row = productRows[i];
  if \(!row || row.length < 2\) continue;
  const status = \(row[statusIdx] || ''\).trim\(\);
  if \(status !== 'PUBLISHED'\) continue;

  const title = \(row[titleIdx] || ''\).replace\(/\\\\s+/g, ' '\).trim\(\);

  // Try to match - normalize both sides
  let matched = false;
  for \(const [remapTitle, catId] of Object.entries\(titleToCatId\)\) {
    // Normalize for comparison
    const normTitle = title.replace\(/[\\\\u201c\\\\u201d\\\\u2018\\\\u2019˚½]/g, m => m\).toLowerCase\(\).trim\(\);
    const normRemap = remapTitle.replace\(/[\\\\u201c\\\\u201d\\\\u2018\\\\u2019˚½]/g, m => m\).toLowerCase\(\).trim\(\);

    if \(normTitle === normRemap || title.includes\(remapTitle\) || remapTitle.includes\(title\)\) {
      row[catRefIdx] = '[\\"' + catId + '\\"]';
      matched = true;
      break;
    }
  }
  if \(!matched\) {
    unmatchedProducts.push\(title\);
  }
}

if \(unmatchedProducts.length > 0\) {
  console.log\('\\\\nWARNING - Unmatched products:'\);
  unmatchedProducts.forEach\(p => console.log\('  - ' + p\)\);
}

// --- 5. Write updated Product+List.csv ---
function escapeField\(val\) {
  if \(val.includes\(','\) || val.includes\('\\"'\) || val.includes\('\\n'\)\) {
    return '\\"' + val.replace\(/\\"/g, '\\"\\"'\) + '\\"';
  }
  return val;
}

const productOut = productRows.map\(row => row.map\(escapeField\).join\(','\)\).join\('\\n'\);
fs.writeFileSync\('data/Product+List.csv', productOut, 'utf8'\);
console.log\('\\\\nWrote data/Product+List.csv'\);

// --- 6. Write new Product+Categories.csv ---
// Build multi-reference for each category \(list of product IDs in that category\)
const catToProductIds = {};
for \(const key of Object.keys\(newCategories\)\) catToProductIds[key] = [];

for \(let i = 1; i < productRows.length; i++\) {
  const row = productRows[i];
  if \(!row || row.length < 2\) continue;
  if \(\(row[statusIdx] || ''\).trim\(\) !== 'PUBLISHED'\) continue;
  const prodId = \(row[idIdx] || ''\).trim\(\);
  const catRef = \(row[catRefIdx] || ''\).trim\(\);

  for \(const [key, cat] of Object.entries\(newCategories\)\) {
    if \(catRef.includes\(cat.id\)\) {
      catToProductIds[key].push\(prodId\);
    }
  }
}

const owner = '9af21d4e-2c70-4ca7-ba14-ceb25a4ffc80';
const now = new Date\(\).toISOString\(\).replace\(/\\\\.\\\\d+Z/, 'Z'\);
let catCsv = '\\"Title\\",\\"Description\\",\\"Image\\",\\"ID\\",\\"Created Date\\",\\"Updated Date\\",\\"Owner\\",\\"Multi-Reference\\",\\"Product Categories \(Item\)\\",\\"Publish Date\\",\\"Unpublish Date\\",\\"Status\\"\\n';

for \(const [key, cat] of Object.entries\(newCategories\)\) {
  const prodIds = catToProductIds[key];
  const multiRef = JSON.stringify\(prodIds\);
  const itemPath = '/product-categories/' + cat.slug;
  catCsv += '\\"' + cat.title + '\\",,,' +
    '\\"' + cat.id + '\\",' +
    now + ',' + now + ',' +
    '\\"' + owner + '\\",' +
    '\\"' + multiRef.replace\(/\\"/g, '\\"\\"'\) + '\\",' +
    '\\"' + itemPath + '\\",' +
    now + ',,' +
    '\\"PUBLISHED\\"\\n';
}

fs.writeFileSync\('data/Product+Categories.csv', catCsv, 'utf8'\);
console.log\('Wrote data/Product+Categories.csv'\);

console.log\('\\\\nDone! Now run sync-catalog to regenerate.'\);
")

